import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken(); int S = (int) st.nval;
        st.nextToken(); int T = (int) st.nval;
        boolean[][] adj = new boolean[S + 1][S + 1];
        for (int i = 0; i < T; i++) {
            st.nextToken(); int x = (int) st.nval;
            st.nextToken(); int y = (int) st.nval;
            adj[x][y] = true;
            adj[y][x] = true;
        }
        st.nextToken(); int P = (int) st.nval;
        int count = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < P; i++) {
            st.nextToken(); int N = (int) st.nval;
            st.nextToken(); int prev = (int) st.nval;
            boolean ok = true;
            for (int j = 1; j < N; j++) {
                st.nextToken(); int cur = (int) st.nval;
                if (!adj[prev][cur]) ok = false;
                prev = cur;
            }
            if (ok) count++;
        }
        sb.append(count);
        System.out.println(sb);
    }
}
